/**
 * CineJoy On-Device Proxy Standalone Test Suite: test-poc-service.js
 *
 * Validates on-device JS Service (poc/service/) prior to TV deployment:
 *   Check 1: Syntax compatibility audit (0 occurrences of ?., ??, _ in poc/service/)
 *   Check 2: Service startup and local HTTP binding (127.0.0.1:8088)
 *   Check 3: GET /health endpoint response and schema validation (RSS < 50MB)
 *   Check 4: GET /api/servers catalog endpoint response
 *   Check 5: GET /api/stream real stream resolution (crush.wasm + AES-256-GCM)
 *   Check 6: GET /hls/proxy?url=... master and variant M3U8 manifest URL rewriting
 *   Check 7: HTTP 206 Partial Content media range request test against Lightspeed CDN
 *   Check 8: Client disconnect abort cleanup test
 *   Check 9: Clean service shutdown
 *
 * RUNTIME COMPATIBILITY:
 *   Strictly compatible with Node.js 12.22.2 through Node.js 26+
 *   No optional chaining (?.), no nullish coalescing (??), no numeric separators (_)
 *   No external npm dependencies. Native Node built-ins only.
 *
 * USAGE:
 *   node poc/test-poc-service.js [--service-dir=<path>] [--port=<port>] [--external] [--verbose]
 */

'use strict';

const http = require('http');
const https = require('https');
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');
const vm = require('vm');
const { URL } = require('url');

// CLI Arguments Parsing (compatible with Node 12)
const args = process.argv.slice(2);
function getArg(prefix, defaultVal) {
  for (let i = 0; i < args.length; i++) {
    if (args[i].indexOf(prefix) === 0) {
      return args[i].substring(prefix.length);
    }
  }
  return defaultVal;
}
function hasFlag(flag) {
  return args.indexOf(flag) !== -1;
}

const DEFAULT_PORT = 8088;
const TEST_HOST = '127.0.0.1';
const portArg = getArg('--port=', process.env.PORT || DEFAULT_PORT.toString());
let activePort = parseInt(portArg, 10) || DEFAULT_PORT;

// Auto-detect service directory
let defaultServiceDir = path.join(__dirname, 'service');
if (!fs.existsSync(defaultServiceDir)) {
  defaultServiceDir = path.join(__dirname, '..', 'poc', 'service');
}
if (!fs.existsSync(defaultServiceDir)) {
  defaultServiceDir = path.join(process.cwd(), 'poc', 'service');
}
const serviceDir = path.resolve(getArg('--service-dir=', defaultServiceDir));
const isExternalMode = hasFlag('--external') || hasFlag('--no-spawn');
const isVerbose = hasFlag('--verbose') || hasFlag('-v');

let serverChildProcess = null;

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  magenta: '\x1b[35m'
};

/**
 * Standard HTTP/HTTPS request helper returning Promise
 */
function request(options, requestBody) {
  return new Promise(function (resolve, reject) {
    const isHttps = options.protocol === 'https:';
    const client = isHttps ? https : http;

    const reqOpts = Object.assign({}, options);
    reqOpts.headers = Object.assign({}, options.headers || {});

    if (requestBody && !reqOpts.headers['Content-Length'] && !reqOpts.headers['content-length']) {
      reqOpts.headers['Content-Length'] = Buffer.isBuffer(requestBody)
        ? requestBody.length
        : Buffer.byteLength(requestBody);
    }

    const req = client.request(reqOpts, function (res) {
      const chunks = [];
      res.on('data', function (chunk) {
        chunks.push(chunk);
      });
      res.on('end', function () {
        const rawBuffer = Buffer.concat(chunks);
        let text = null;
        let json = null;
        try {
          text = rawBuffer.toString('utf8');
          json = JSON.parse(text);
        } catch (_) {}
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          buffer: rawBuffer,
          text: text,
          json: json
        });
      });
    });

    req.on('error', reject);

    const timeoutMs = options.timeout || 15000;
    req.setTimeout(timeoutMs, function () {
      req.abort();
      reject(new Error('Request timed out after ' + timeoutMs + 'ms'));
    });

    if (requestBody) {
      req.write(requestBody);
    }
    req.end();
  });
}

/**
 * Polls the /health endpoint until the service is ready or timeout expires
 */
function waitForServer(port, maxWaitMs) {
  maxWaitMs = maxWaitMs || 6000;
  const start = Date.now();
  return new Promise(function (resolve) {
    function check() {
      if (Date.now() - start >= maxWaitMs) {
        return resolve(false);
      }
      request({
        hostname: TEST_HOST,
        port: port,
        path: '/health',
        method: 'GET',
        timeout: 1000
      })
        .then(function (res) {
          if (res.statusCode === 200 && res.json && res.json.status === 'ok') {
            resolve(true);
          } else {
            setTimeout(check, 100);
          }
        })
        .catch(function () {
          setTimeout(check, 100);
        });
    }
    check();
  });
}

/**
 * Simple test assertion helper
 */
function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Assertion failed');
  }
}

// Test Runner Framework
let totalTests = 0;
let passedTests = 0;
let failedTests = 0;
const testResults = [];

function runTest(testName, testFn) {
  totalTests++;
  const testNumber = totalTests;
  process.stdout.write('  [' + testNumber + '] ' + testName + ' ... ');
  const startTime = Date.now();

  return Promise.resolve()
    .then(function () {
      return testFn();
    })
    .then(function () {
      const duration = Date.now() - startTime;
      console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(' + duration + 'ms)' + C.reset);
      passedTests++;
      testResults.push({ name: testName, pass: true, duration: duration });
    })
    .catch(function (err) {
      const duration = Date.now() - startTime;
      console.log(C.red + C.bold + '✖ FAIL' + C.reset + ' ' + C.gray + '(' + duration + 'ms)' + C.reset);
      console.error('      ' + C.red + 'Error: ' + err.message + C.reset);
      failedTests++;
      testResults.push({ name: testName, pass: false, error: err.message, duration: duration });
    });
}

/**
 * Main Test Execution Function
 */
async function main() {
  console.log('\n' + C.bold + C.cyan + '================================================================' + C.reset);
  console.log(C.bold + C.cyan + '   CINEJOY ON-DEVICE PROXY: STANDALONE SERVICE TEST SUITE       ' + C.reset);
  console.log(C.bold + C.cyan + '================================================================' + C.reset + '\n');

  console.log(C.bold + '► Environment Runtime Profile:' + C.reset);
  console.log('  Node.js:   ' + process.version + ' (Modules: ' + process.versions.modules + ')');
  console.log('  V8 Engine: ' + process.versions.v8);
  console.log('  Platform:  ' + process.platform + ' ' + process.arch);
  console.log('  Target:    LG webOS 8.5.0 (Node 12.22.2 standard)');
  console.log('  Service:   ' + serviceDir);
  console.log('  Port:      ' + activePort + '\n');

  // Shared test context across checks
  let resolvedStreamUrl = null;
  let resolvedOriginalUrl = null;
  let resolvedVariantProxyUrl = null;
  let resolvedMediaSegmentProxyUrl = null;
  let resolvedInitSegmentProxyUrl = null;

  // -------------------------------------------------------------------------
  // Check 1: Syntax compatibility audit
  // -------------------------------------------------------------------------
  await runTest('Check 1: Syntax compatibility audit (Node 12.22.2 strict sweep)', function () {
    assert(fs.existsSync(serviceDir), 'Service directory does not exist: ' + serviceDir);

    const requiredFiles = ['index.js', 'resolver.js', 'hls-proxy.js', 'http-client.js'];
    const violations = [];

    for (let i = 0; i < requiredFiles.length; i++) {
      const filename = requiredFiles[i];
      const filePath = path.join(serviceDir, filename);

      assert(fs.existsSync(filePath), 'Required service file missing: ' + filename);

      const content = fs.readFileSync(filePath, 'utf8');

      // V8 Script Compilation Check
      try {
        new vm.Script(content, { filename: filename, displayErrors: true });
      } catch (scriptErr) {
        violations.push({
          file: filename,
          line: scriptErr.lineNumber || 1,
          type: 'V8 Syntax Error',
          snippet: scriptErr.message
        });
      }

      // AST / Regex Lexical Audit
      const lines = content.split('\n');
      for (let l = 0; l < lines.length; l++) {
        const lineNum = l + 1;
        const line = lines[l];
        const trimmed = line.trim();

        // Skip comment lines
        if (trimmed.indexOf('//') === 0 || trimmed.indexOf('*') === 0) continue;

        // Check 1.1: Optional chaining (?.)
        if (/\?\.(?!\d)/.test(line)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Optional chaining (?.)',
            snippet: trimmed
          });
        }

        // Check 1.2: Nullish coalescing (??)
        if (/\?\?/.test(line)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Nullish coalescing (??)',
            snippet: trimmed
          });
        }

        // Check 1.3: Numeric separator (_)
        if (/\b\d+_\d+\b/.test(line)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Numeric separator (_)',
            snippet: trimmed
          });
        }

        // Check 1.4: Node 18+ AbortSignal.timeout
        if (/\bAbortSignal\.timeout\b/.test(line)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'AbortSignal.timeout (Node 18+)',
            snippet: trimmed
          });
        }

        // Check 1.5: Node 18+ Readable.fromWeb
        if (/\bReadable\.fromWeb\b/.test(line)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Readable.fromWeb (Node 18+)',
            snippet: trimmed
          });
        }

        // Check 1.6: Node 18+ Global fetch()
        if (/\b(?<![.\w])fetch\s*\(/.test(line)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Global fetch() (Node 18+)',
            snippet: trimmed
          });
        }

        // Check 1.7: Node 15+ crypto.webcrypto
        if (/\bcrypto\.webcrypto\b/.test(line)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'crypto.webcrypto (Node 15+)',
            snippet: trimmed
          });
        }
      }
    }

    if (violations.length > 0) {
      let msg = 'Found ' + violations.length + ' Node 12 incompatible syntax/API occurrences:\n';
      for (let v = 0; v < violations.length; v++) {
        const item = violations[v];
        msg += '    ' + item.file + ':' + item.line + ' [' + item.type + '] ' + item.snippet + '\n';
      }
      throw new Error(msg);
    }

    // Verify crush.wasm exists and is valid
    const wasmPath = path.join(serviceDir, 'crush.wasm');
    assert(fs.existsSync(wasmPath), 'crush.wasm binary is missing from service directory: ' + wasmPath);
    const wasmStat = fs.statSync(wasmPath);
    assert(wasmStat.size >= 65000, 'crush.wasm size is suspiciously small: ' + wasmStat.size + ' bytes');
  });

  // -------------------------------------------------------------------------
  // Check 2: Service startup and local HTTP binding
  // -------------------------------------------------------------------------
  await runTest('Check 2: Service startup and local HTTP binding (127.0.0.1:' + activePort + ')', async function () {
    const isAlreadyRunning = await waitForServer(activePort, 800);
    if (isAlreadyRunning) {
      if (isVerbose) console.log('    Connected to already running service on port ' + activePort);
      return;
    }

    if (isExternalMode) {
      throw new Error('Service is not running on 127.0.0.1:' + activePort + ' and --external mode was requested');
    }

    const entryPoint = path.join(serviceDir, 'index.js');
    assert(fs.existsSync(entryPoint), 'Service entry point missing: ' + entryPoint);

    const env = Object.assign({}, process.env, {
      PORT: activePort.toString(),
      NODE_PATH: process.env.NODE_PATH || '/usr/lib/nodejs:/usr/lib/node_modules'
    });

    serverChildProcess = spawn(process.execPath, [entryPoint], {
      stdio: ['ignore', 'pipe', 'pipe'],
      env: env
    });

    serverChildProcess.stderr.on('data', function (data) {
      if (isVerbose) process.stderr.write(C.gray + '[service stderr] ' + data.toString() + C.reset);
    });

    serverChildProcess.stdout.on('data', function (data) {
      if (isVerbose) process.stdout.write(C.gray + '[service stdout] ' + data.toString() + C.reset);
    });

    const isReady = await waitForServer(activePort, 6000);
    assert(isReady, 'Service failed to bind and respond on 127.0.0.1:' + activePort + ' within 6000ms');
  });

  // -------------------------------------------------------------------------
  // Check 3: GET /health endpoint response and schema validation
  // -------------------------------------------------------------------------
  await runTest('Check 3: GET /health endpoint response and schema validation', async function () {
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/health',
      method: 'GET'
    });

    assert(res.statusCode === 200, 'Expected status 200, got ' + res.statusCode);
    assert(res.headers['access-control-allow-origin'] === '*', 'Missing CORS Access-Control-Allow-Origin: *');

    const json = res.json;
    assert(json && typeof json === 'object', 'Response body is not valid JSON');
    assert(json.status === 'ok', 'Expected status === "ok", got: ' + json.status);
    assert(json.mode === 'on-device-service', 'Expected mode === "on-device-service", got: ' + json.mode);
    assert(typeof json.uptime === 'number' && json.uptime >= 0, 'Missing or invalid uptime');
    assert(json.memory && typeof json.memory === 'object', 'Missing memory usage object');
    assert(typeof json.memory.rss === 'number' && json.memory.rss > 0, 'Invalid memory.rss value');

    // Safe RAM budget verification: Service must consume less than 50 MB RSS on webOS
    const rssMb = (json.memory.rss / (1024 * 1024)).toFixed(2);
    assert(
      json.memory.rss < 50 * 1024 * 1024,
      'Service RSS exceeds 50 MB budget: ' + rssMb + ' MB'
    );
    if (isVerbose) console.log('    Current Service RSS: ' + rssMb + ' MB (Budget: <50 MB)');
  });

  // -------------------------------------------------------------------------
  // Check 4: GET /api/servers catalog endpoint response
  // -------------------------------------------------------------------------
  await runTest('Check 4: GET /api/servers catalog endpoint response', async function () {
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/servers',
      method: 'GET'
    });

    assert(res.statusCode === 200, 'Expected status 200, got ' + res.statusCode);
    assert(res.headers['access-control-allow-origin'] === '*', 'Missing CORS header on /api/servers');

    const json = res.json;
    assert(json && Array.isArray(json.servers), 'Expected servers array in response');
    assert(json.servers.length > 0, 'Servers list is empty');

    let hasSecretServer = false;
    for (let i = 0; i < json.servers.length; i++) {
      const s = json.servers[i];
      assert(typeof s.name === 'string', 'Server name must be a string');
      if (s.name === 'secret') {
        hasSecretServer = true;
      }
    }
    assert(hasSecretServer, 'Primary streaming server "secret" not found in servers list');
  });

  // -------------------------------------------------------------------------
  // Check 5: GET /api/stream real stream resolution (crush.wasm + AES-256-GCM)
  // -------------------------------------------------------------------------
  await runTest('Check 5: GET /api/stream real stream resolution (crush.wasm + AES-256-GCM)', async function () {
    // TMDB 550 = Fight Club (canonical test movie)
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/stream?tmdbId=550&type=movie&server=secret',
      method: 'GET'
    });

    assert(res.statusCode === 200, 'Expected status 200, got ' + res.statusCode + ' (' + res.text + ')');
    assert(res.headers['access-control-allow-origin'] === '*', 'Missing CORS header on stream resolution');

    const json = res.json;
    assert(json && json.success === true, 'Expected success: true, got ' + JSON.stringify(json));
    assert(typeof json.streamUrl === 'string', 'streamUrl must be a string');
    assert(
      json.streamUrl.indexOf('http://' + TEST_HOST + ':' + activePort + '/hls/proxy?url=') === 0,
      'streamUrl does not point to local proxy: ' + json.streamUrl
    );
    assert(typeof json.originalUrl === 'string', 'originalUrl must be a string');
    assert(
      json.originalUrl.indexOf('lightspeed.st') !== -1 || json.originalUrl.indexOf('.m3u8') !== -1,
      'originalUrl does not target valid stream playlist: ' + json.originalUrl
    );
    assert(json.server === 'secret', 'Expected server === "secret", got: ' + json.server);

    resolvedStreamUrl = json.streamUrl;
    resolvedOriginalUrl = json.originalUrl;

    if (isVerbose) {
      console.log('    Original Playlist: ' + resolvedOriginalUrl);
      console.log('    Proxied Stream:   ' + resolvedStreamUrl);
    }
  });

  // -------------------------------------------------------------------------
  // Check 6: GET /hls/proxy?url=... master and variant M3U8 manifest URL rewriting
  // -------------------------------------------------------------------------
  await runTest('Check 6: GET /hls/proxy?url=... master and variant M3U8 manifest URL rewriting', async function () {
    assert(resolvedStreamUrl, 'Prerequisite failed: Check 5 did not yield resolvedStreamUrl');

    const proxyPath = resolvedStreamUrl.replace('http://' + TEST_HOST + ':' + activePort, '');
    const masterRes = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: proxyPath,
      method: 'GET'
    });

    assert(masterRes.statusCode === 200, 'Master playlist returned ' + masterRes.statusCode);
    assert(masterRes.headers['access-control-allow-origin'] === '*', 'Missing CORS header on master manifest');
    assert(
      masterRes.text && masterRes.text.indexOf('#EXTM3U') === 0,
      'Master manifest does not start with #EXTM3U'
    );

    // Parse and verify rewritten variant URLs
    const masterLines = masterRes.text.split('\n');
    const variantUrls = [];
    for (let i = 0; i < masterLines.length; i++) {
      const line = masterLines[i].trim();
      if (line && line.indexOf('#') !== 0) {
        variantUrls.push(line);
      }
    }
    assert(variantUrls.length > 0, 'No variant playlists found in master manifest');

    const expectedPrefix = 'http://' + TEST_HOST + ':' + activePort + '/hls/proxy?url=';
    for (let v = 0; v < variantUrls.length; v++) {
      assert(
        variantUrls[v].indexOf(expectedPrefix) === 0,
        'Variant URL not rewritten to local proxy: ' + variantUrls[v]
      );
    }

    resolvedVariantProxyUrl = variantUrls[0];

    // Fetch and verify variant manifest
    const variantPath = resolvedVariantProxyUrl.replace('http://' + TEST_HOST + ':' + activePort, '');
    const variantRes = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: variantPath,
      method: 'GET'
    });

    assert(variantRes.statusCode === 200, 'Variant manifest returned ' + variantRes.statusCode);
    assert(
      variantRes.text && variantRes.text.indexOf('#EXTM3U') === 0,
      'Variant manifest does not start with #EXTM3U'
    );

    // Check for initialization map (#EXT-X-MAP) and segments
    const mapMatch = variantRes.text.match(/#EXT-X-MAP:URI="([^"]+)"/);
    if (mapMatch && mapMatch[1]) {
      resolvedInitSegmentProxyUrl = mapMatch[1];
      assert(
        resolvedInitSegmentProxyUrl.indexOf(expectedPrefix) === 0,
        'Init segment URI not rewritten to local proxy: ' + resolvedInitSegmentProxyUrl
      );
    }

    // Extract first media segment URL
    const variantLines = variantRes.text.split('\n');
    for (let s = 0; s < variantLines.length; s++) {
      const segLine = variantLines[s].trim();
      if (segLine && segLine.indexOf('#') !== 0) {
        resolvedMediaSegmentProxyUrl = segLine;
        break;
      }
    }
    assert(resolvedMediaSegmentProxyUrl, 'No media segment URLs found in variant manifest');
    assert(
      resolvedMediaSegmentProxyUrl.indexOf(expectedPrefix) === 0,
      'Media segment URL not rewritten: ' + resolvedMediaSegmentProxyUrl
    );
  });

  // -------------------------------------------------------------------------
  // Check 7: HTTP 206 Partial Content media range request test against Lightspeed CDN
  // -------------------------------------------------------------------------
  await runTest('Check 7: HTTP 206 Partial Content media range request test against Lightspeed CDN', async function () {
    // Use init segment if available, otherwise first media chunk
    const targetProxyUrl = resolvedInitSegmentProxyUrl || resolvedMediaSegmentProxyUrl;
    assert(targetProxyUrl, 'Prerequisite failed: Check 6 did not yield a segment proxy URL');

    const segmentPath = targetProxyUrl.replace('http://' + TEST_HOST + ':' + activePort, '');
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: segmentPath,
      method: 'GET',
      headers: {
        Range: 'bytes=0-1023',
        Origin: 'https://cinejoy.pk'
      }
    });

    assert(
      res.statusCode === 206 || res.statusCode === 200,
      'Expected HTTP 206 Partial Content (or 200), got ' + res.statusCode
    );
    assert(res.buffer && res.buffer.length > 0, 'Media chunk returned empty buffer');
    assert(res.headers['access-control-allow-origin'] === '*', 'Missing CORS on media segment');

    if (res.statusCode === 206) {
      assert(res.headers['content-range'], 'HTTP 206 response missing Content-Range header');
      assert(res.buffer.length <= 1024, 'Range request returned more bytes than requested');
    }

    // If init segment was fetched, verify ISO BMFF ftyp box header at offset 4..8
    if (resolvedInitSegmentProxyUrl && targetProxyUrl === resolvedInitSegmentProxyUrl) {
      assert(res.buffer.length >= 8, 'Init segment buffer too short (<8 bytes)');
      const boxType = res.buffer.subarray(4, 8).toString('ascii');
      assert(
        boxType === 'ftyp',
        'Init segment corrupted! Expected "ftyp" box header at offset 4..8, got: ' + boxType
      );
    }
  });

  // -------------------------------------------------------------------------
  // Check 8: Client disconnect abort cleanup test
  // -------------------------------------------------------------------------
  await runTest('Check 8: Client disconnect abort cleanup test', function () {
    return new Promise(function (resolve, reject) {
      const targetUrl = resolvedMediaSegmentProxyUrl || resolvedInitSegmentProxyUrl;
      assert(targetUrl, 'Prerequisite failed: No media segment URL available for abort test');

      const segmentPath = targetUrl.replace('http://' + TEST_HOST + ':' + activePort, '');

      let clientAborted = false;
      const req = http.request({
        hostname: TEST_HOST,
        port: activePort,
        path: segmentPath,
        method: 'GET',
        headers: {
          Origin: 'https://cinejoy.pk'
        }
      }, function (res) {
        // Abort as soon as first data chunk is received
        res.on('data', function () {
          if (!clientAborted) {
            clientAborted = true;
            req.abort();
          }
        });
      });

      req.on('error', function (err) {
        if (!clientAborted) {
          reject(new Error('Unexpected client error prior to abort: ' + err.message));
        }
      });

      req.on('close', function () {
        if (clientAborted) {
          // Wait 200ms to allow server-side req.on('close') cleanup to execute
          setTimeout(function () {
            request({
              hostname: TEST_HOST,
              port: activePort,
              path: '/health',
              method: 'GET'
            })
              .then(function (healthRes) {
                if (healthRes.statusCode === 200 && healthRes.json && healthRes.json.status === 'ok') {
                  resolve();
                } else {
                  reject(new Error('Server degraded or not ok after client abort: status ' + healthRes.statusCode));
                }
              })
              .catch(function (healthErr) {
                reject(new Error('Server crashed or unresponsive after client abort: ' + healthErr.message));
              });
          }, 200);
        }
      });

      req.end();
    });
  });

  // -------------------------------------------------------------------------
  // Check 9: Clean service shutdown
  // -------------------------------------------------------------------------
  await runTest('Check 9: Clean service shutdown', function () {
    return new Promise(function (resolve, reject) {
      if (!serverChildProcess) {
        if (isVerbose) console.log('    External server mode: skipping child process SIGTERM');
        return resolve();
      }

      const killTimeout = setTimeout(function () {
        try {
          serverChildProcess.kill('SIGKILL');
        } catch (_) {}
        reject(new Error('Service failed to exit within 3000ms after SIGTERM'));
      }, 3000);

      serverChildProcess.on('exit', function (code, signal) {
        clearTimeout(killTimeout);
        serverChildProcess = null;

        // Verify port 8088 is completely released
        setTimeout(function () {
          request({
            hostname: TEST_HOST,
            port: activePort,
            path: '/health',
            method: 'GET',
            timeout: 500
          })
            .then(function () {
              reject(new Error('Port ' + activePort + ' is still accepting connections after service exit'));
            })
            .catch(function (err) {
              // Expected error: ECONNREFUSED or socket error
              resolve();
            });
        }, 150);
      });

      serverChildProcess.kill('SIGTERM');
    });
  });

  // -------------------------------------------------------------------------
  // Phase 3: Final Test Execution Summary
  // -------------------------------------------------------------------------
  console.log('\n' + C.bold + '► Test Execution Summary' + C.reset);
  console.log('----------------------------------------------------------------');
  console.log('  Total Checks Run: ' + totalTests);
  console.log('  Passed Checks:    ' + C.green + passedTests + C.reset);
  console.log('  Failed Checks:    ' + (failedTests > 0 ? C.red + failedTests : '0') + C.reset);
  console.log('----------------------------------------------------------------');

  if (serverChildProcess) {
    try {
      serverChildProcess.kill('SIGKILL');
    } catch (_) {}
  }

  if (failedTests > 0) {
    console.log('\n' + C.red + C.bold + 'VERDICT: TEST SUITE FAILED (' + failedTests + ' failures)' + C.reset + '\n');
    process.exit(1);
  } else {
    console.log('\n' + C.green + C.bold + 'VERDICT: ALL 9 CHECKS PASSED (100% SUCCESS)' + C.reset + '\n');
    process.exit(0);
  }
}

main().catch(function (fatalErr) {
  console.error('\n' + C.red + 'Fatal test runner exception:' + C.reset, fatalErr);
  if (serverChildProcess) {
    try {
      serverChildProcess.kill('SIGKILL');
    } catch (_) {}
  }
  process.exit(1);
});

