for (let i = 0; i < requiredFiles.length; i++) {
  const filename = requiredFiles[i];
  const filePath = path.join(serviceDir, filename);

  assert(fs.existsSync(filePath), 'Required service file missing: ' + filename);

  const content = fs.readFileSync(filePath, 'utf8');

  // V8 Script Compilation Check
  try {
    new vm.Script(content, { filename: filename, displayErrors: true });
  } catch (scriptErr) {
    violations.push({
      file: filename,
      line: scriptErr.lineNumber || 1,
      type: 'V8 Syntax Error',
      snippet: scriptErr.message
    });
  }

  // AST / Regex Lexical Audit
  const lines = content.split('\n');
  for (let l = 0; l < lines.length; l++) {
    const lineNum = l + 1;
    const line = lines[l];
    const trimmed = line.trim();

    // Skip comment lines
    if (trimmed.indexOf('//') === 0 || trimmed.indexOf('*') === 0) continue;

    // Check 1.1: Optional chaining (?.)
    if (/\?\.(?!\d)/.test(line)) {
      violations.push({
        file: filename,
        line: lineNum,
        type: 'Optional chaining (?.)',
        snippet: trimmed
      });
    }

    // Check 1.2: Nullish coalescing (??)
    if (/\?\?/.test(line)) {
      violations.push({
        file: filename,
        line: lineNum,
        type: 'Nullish coalescing (??)',
        snippet: trimmed
      });
    }

    // Check 1.3: Numeric separator (_)
    if (/\b\d+_\d+\b/.test(line)) {
      violations.push({
        file: filename,
        line: lineNum,
        type: 'Numeric separator (_)',
        snippet: trimmed
      });
    }

    // Check 1.4: Node 18+ AbortSignal.timeout
    if (/\bAbortSignal\.timeout\b/.test(line)) {
      violations.push({
        file: filename,
        line: lineNum,
        type: 'AbortSignal.timeout (Node 18+)',
        snippet: trimmed
      });
    }

    // Check 1.5: Node 18+ Readable.fromWeb
    if (/\bReadable\.fromWeb\b/.test(line)) {
      violations.push({
        file: filename,
        line: lineNum,
        type: 'Readable.fromWeb (Node 18+)',
        snippet: trimmed
      });
    }

    // Check 1.6: Node 18+ Global fetch()
    if (/\b(?<![.\w])fetch\s*\(/.test(line)) {
      violations.push({
        file: filename,
        line: lineNum,
        type: 'Global fetch() (Node 18+)',
        snippet: trimmed
      });
    }

    // Check 1.7: Node 15+ crypto.webcrypto
    if (/\bcrypto\.webcrypto\b/.test(line)) {
      violations.push({
        file: filename,
        line: lineNum,
        type: 'crypto.webcrypto (Node 15+)',
        snippet: trimmed
      });
    }
  }
}

