/**
 * Standalone IPK Package Verification Script: verify-ipk.js
 *
 * Verifies dist_poc/com.cinejoy.poc_1.0.0_all.ipk:
 *   1. Archive integrity: debian-binary, control.tar.gz, data.tar.gz
 *   2. Control manifest: Package id, version, architecture
 *   3. Package mapping: usr/palm/packages/com.cinejoy.poc/packageinfo.json
 *   4. App assets: appinfo.json, index.html, icons, styles, scripts
 *   5. Service assets: services.json, package.json, index.js, resolver.js,
 *                      hls-proxy.js, http-client.js, crush.wasm
 *   6. Manifest cross-validation (packageinfo.json ↔ appinfo.json ↔ services.json)
 *
 * Compatible with Node 12.22.2 through Node 26+ (Zero external npm dependencies)
 *
 * Usage:
 *   node poc/verify-ipk.js [path/to/com.cinejoy.poc_1.0.0_all.ipk]
 */

'use strict';

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const defaultIpkPath = path.join(process.cwd(), 'dist_poc', 'com.cinejoy.poc_1.0.0_all.ipk');
const targetIpk = process.argv[2] ? path.resolve(process.argv[2]) : defaultIpkPath;

const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m'
};

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Assertion failed');
  }
}

function runCommand(cmd) {
  try {
    return execSync(cmd, { stdio: ['ignore', 'pipe', 'pipe'] }).toString('utf8');
  } catch (err) {
    throw new Error('Command failed: ' + cmd + '\n' + (err.stderr ? err.stderr.toString('utf8') : err.message));
  }
}

function main() {
  console.log('\n' + C.bold + C.cyan + '================================================================' + C.reset);
  console.log(C.bold + C.cyan + '   CINEJOY STANDALONE IPK PACKAGE VERIFICATION HARNESS         ' + C.reset);
  console.log(C.bold + C.cyan + '================================================================' + C.reset + '\n');

  console.log('Target IPK: ' + targetIpk);

  // Step 1: File Existence & Size
  process.stdout.write('  [1/6] Validating IPK file existence and minimum size ... ');
  assert(fs.existsSync(targetIpk), 'IPK file not found at: ' + targetIpk);
  const stat = fs.statSync(targetIpk);
  assert(stat.size > 50000, 'IPK file size suspiciously small: ' + stat.size + ' bytes');
  console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(' + (stat.size / 1024).toFixed(1) + ' KB)' + C.reset);

  // Step 2: Archive Container Format (Debian binary format)
  process.stdout.write('  [2/6] Verifying ar archive members (debian-binary, control, data) ... ');
  const arList = runCommand('ar -t "' + targetIpk + '"');
  const arMembers = arList.split('\n').map(function (s) { return s.trim(); }).filter(Boolean);
  assert(arMembers.indexOf('debian-binary') !== -1, 'Missing debian-binary member');
  assert(arMembers.indexOf('control.tar.gz') !== -1, 'Missing control.tar.gz member');
  assert(arMembers.indexOf('data.tar.gz') !== -1, 'Missing data.tar.gz member');
  console.log(C.green + C.bold + '✔ PASS' + C.reset);

  // Step 3: Control Metadata Validation
  process.stdout.write('  [3/6] Inspecting control.tar.gz metadata ... ');
  const controlContent = runCommand('ar -p "' + targetIpk + '" control.tar.gz | tar -zxf - control -O');
  assert(controlContent.indexOf('Package: com.cinejoy.poc') !== -1, 'Missing Package: com.cinejoy.poc in control file');
  assert(controlContent.indexOf('Version: 1.0.0') !== -1, 'Missing Version: 1.0.0 in control file');
  assert(controlContent.indexOf('Architecture: all') !== -1, 'Expected Architecture: all in control file');
  console.log(C.green + C.bold + '✔ PASS' + C.reset);

  // Step 4: Data Directory Layout Validation
  process.stdout.write('  [4/6] Checking required file entries in data.tar.gz ... ');
  const dataList = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -ztvf -');
  const expectedEntries = [
    'usr/palm/applications/com.cinejoy.poc/appinfo.json',
    'usr/palm/applications/com.cinejoy.poc/index.html',
    'usr/palm/packages/com.cinejoy.poc/packageinfo.json',
    'usr/palm/services/com.cinejoy.poc.service/services.json',
    'usr/palm/services/com.cinejoy.poc.service/package.json',
    'usr/palm/services/com.cinejoy.poc.service/index.js',
    'usr/palm/services/com.cinejoy.poc.service/resolver.js',
    'usr/palm/services/com.cinejoy.poc.service/hls-proxy.js',
    'usr/palm/services/com.cinejoy.poc.service/http-client.js',
    'usr/palm/services/com.cinejoy.poc.service/crush.wasm'
  ];

  for (let i = 0; i < expectedEntries.length; i++) {
    const entry = expectedEntries[i];
    assert(dataList.indexOf(entry) !== -1, 'Required entry missing from IPK: ' + entry);
  }
  console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(10/10 entries verified)' + C.reset);

  // Step 5: Manifest Cross-Validation
  process.stdout.write('  [5/6] Cross-validating packageinfo.json, appinfo.json, services.json ... ');

  // Read packageinfo.json
  const pkgRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/packages/com.cinejoy.poc/packageinfo.json -O');
  const pkgJson = JSON.parse(pkgRaw);
  assert(pkgJson.id === 'com.cinejoy.poc', 'packageinfo.json id mismatch: ' + pkgJson.id);
  assert(pkgJson.app === 'com.cinejoy.poc', 'packageinfo.json app mismatch: ' + pkgJson.app);
  assert(Array.isArray(pkgJson.services) && pkgJson.services.indexOf('com.cinejoy.poc.service') !== -1, 'packageinfo.json missing service com.cinejoy.poc.service');

  // Read appinfo.json
  const appRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/applications/com.cinejoy.poc/appinfo.json -O');
  const appJson = JSON.parse(appRaw);
  assert(appJson.id === 'com.cinejoy.poc', 'appinfo.json id mismatch: ' + appJson.id);
  assert(appJson.version === '1.0.0', 'appinfo.json version mismatch: ' + appJson.version);
  assert(appJson.main === 'index.html', 'appinfo.json main mismatch: ' + appJson.main);
  assert(appJson.resolution === '1920x1080', 'appinfo.json resolution mismatch: ' + appJson.resolution);

  // Read services.json
  const srvRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.poc.service/services.json -O');
  const srvJson = JSON.parse(srvRaw);
  assert(srvJson.id === 'com.cinejoy.poc.service', 'services.json id mismatch: ' + srvJson.id);
  assert(Array.isArray(srvJson.services) && srvJson.services[0].name === 'com.cinejoy.poc.service', 'services.json service registration mismatch');
  console.log(C.green + C.bold + '✔ PASS' + C.reset);

  // Step 6: ares-package Inspection Compatibility
  process.stdout.write('  [6/6] Verifying SDK tooling compatibility (ares-package -I) ... ');
  const aresOutput = runCommand('ares-package -I "' + targetIpk + '"');
  assert(aresOutput.indexOf('< packageinfo.json >') !== -1, 'ares-package -I failed to parse packageinfo.json');
  assert(aresOutput.indexOf('< appinfo.json >') !== -1, 'ares-package -I failed to parse appinfo.json');
  assert(aresOutput.indexOf('< services.json >') !== -1, 'ares-package -I failed to parse services.json');
  console.log(C.green + C.bold + '✔ PASS' + C.reset);

  console.log('\n' + C.green + C.bold + 'IPK VERIFICATION SUCCESS: ' + targetIpk + ' is fully compliant and ready for TV deployment!' + C.reset + '\n');
}

try {
  main();
  process.exit(0);
} catch (err) {
  console.error('\n' + C.red + C.bold + '✖ IPK VERIFICATION FAILED:' + C.reset + ' ' + err.message + '\n');
  process.exit(1);
}

