```javascript
/**
 * CineJoy On-Device Proxy Standalone Test Suite: test-poc-service.js
 *
 * Validates on-device JS Service (poc/service/) prior to TV deployment:
 *   Check 1: Syntax compatibility audit (0 occurrences of ?., ??, _ in poc/service/)
 *   Check 2: Service startup and local HTTP binding (127.0.0.1:8088)
 *   Check 3: GET /health endpoint response and schema validation (RSS < 50MB)
 *   Check 4: GET /api/servers catalog endpoint response
 *   Check 5: GET /api/stream real stream resolution (crush.wasm + AES-256-GCM)
 *   Check 6: GET /hls/proxy?url=... master and variant M3U8 manifest URL rewriting
 *   Check 7: HTTP 206 Partial Content media range request test against Lightspeed CDN
 *   Check 8: Client disconnect abort cleanup test
 *   Check 9: Clean service shutdown
 *
 * RUNTIME COMPATIBILITY:
 *   Strictly compatible with Node.js 12.22.2 through Node.js 26+
 *   No optional chaining (?.), no nullish coalescing (??), no numeric separators (_)
 *   No external npm dependencies. Native Node built-ins only.
 *
 * USAGE:
 *   node poc/test-poc-service.js [--service-dir=<path>] [--port=<port>] [--external] [--verbose]
 */

'use strict';

const http = require('http');
const https = require('https');
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');
const vm = require('vm');
const { URL } = require('url');

// CLI Arguments Parsing (compatible with Node 12)
const args = process.argv.slice(2);
function getArg(prefix, defaultVal) {
  for (let i = 0; i < args.length; i++) {
    if (args[i].indexOf(prefix) === 0) {
      return args[i].substring(prefix.length);
    }
  }
  return defaultVal;
}
function hasFlag(flag) {
  return args.indexOf(flag) !== -1;
}

const DEFAULT_PORT = 8088;
const TEST_HOST = '127.0.0.1';
const portArg = getArg('--port=', process.env.PORT || DEFAULT_PORT.toString());
let activePort = parseInt(portArg, 10) || DEFAULT_PORT;

// Auto-detect service directory
let defaultServiceDir = path.join(__dirname, 'service');
if (!fs.existsSync(defaultServiceDir)) {
  defaultServiceDir = path.join(__dirname, '..', 'poc', 'service');
}
if (!fs.existsSync(defaultServiceDir)) {
  defaultServiceDir = path.join(process.cwd(), 'poc', 'service');
}
const serviceDir = path.resolve(getArg('--service-dir=', defaultServiceDir));
const isExternalMode = hasFlag('--external') || hasFlag('--no-spawn');
const isVerbose = hasFlag('--verbose') || hasFlag('-v');

let serverChildProcess = null;

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  magenta: '\x1b[35m'
};

/**
 * Standard HTTP/HTTPS request helper returning Promise
 */
function request(options, requestBody) {
  return new Promise(function (resolve, reject) {
    const isHttps = options.protocol === 'https:';
    const client = isHttps ? https : http;

    const reqOpts = Object.assign({}, options);
    reqOpts.headers = Object.assign({}, options.headers || {});

    if (requestBody && !reqOpts.headers['Content-Length'] && !reqOpts.headers['content-length']) {
      reqOpts.headers['Content-Length'] = Buffer.isBuffer(requestBody)
        ? requestBody.length
        : Buffer.byteLength(requestBody);
    }

    const req = client.request(reqOpts, function (res) {
      const chunks = [];
      res.on('data', function (chunk) {
        chunks.push(chunk);
      });
      res.on('end', function () {
        const rawBuffer = Buffer.concat(chunks);
        let text = null;
        let json = null;
        try {
          text = rawBuffer.toString('utf8');
          json = JSON.parse(text);
        } catch (_) {}
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          buffer: rawBuffer,
          text: text,
          json: json
        });
      });
    });

    req.on('error', reject);

    const timeoutMs = options.timeout || 15000;
    req.setTimeout(timeoutMs, function () {
      req.abort();
      reject(new Error('Request timed out after ' + timeoutMs + 'ms'));
    });

    if (requestBody) {
      req.write(requestBody);
    }
    req.end();
  });
}

/**
 * Polls the /health endpoint until the service is ready or timeout expires
 */
function waitForServer(port, maxWaitMs) {
  maxWaitMs = maxWaitMs || 6000;
  const start = Date.now();
  return new Promise(function (resolve) {
    function check() {
      if (Date.now() - start >= maxWaitMs) {
        return resolve(false);
      }
      request({
        hostname: TEST_HOST,
        port: port,
        path: '/health',
        method: 'GET',
        timeout: 1000
      })
        .then(function (res) {
          if (res.statusCode === 200 && res.json && res.json.status === 'ok') {
            resolve(true);
          } else {
            setTimeout(check, 100);
          }
        })
        .catch(function () {
          setTimeout(check, 100);
        });
    }
    check();
  });
}

/**
 * Simple test assertion helper
 */
function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Assertion failed');
  }
}

// Test Runner Framework
let totalTests = 0;
let passedTests = 0;
let failedTests = 0;
const testResults = [];

function runTest(testName, testFn) {
  totalTests++;
  const testNumber = totalTests;
  process.stdout.write('  [' + testNumber + '] ' + testName + ' ... ');
  const startTime = Date.now();

  return Promise.resolve()
    .then(function () {
      return testFn();
    })
    .then(function () {
      const duration = Date.now() - startTime;
      console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(' + duration + 'ms)' + C.reset);
      passedTests++;
      testResults.push({ name: testName, pass: true, duration: duration });
    })
    .catch(function (err) {
      const duration = Date.now() - startTime;
      console.log(C.red + C.bold + '✖ FAIL' + C.reset + ' ' + C.gray + '(' + duration + 'ms)' + C.reset);
      console.error('      ' + C.red + 'Error: ' + err.message + C.reset);
      failedTests++;
      testResults.push({ name: testName, pass: false, error: err.message, duration: duration });
    });
}

/**
 * Main Test Execution Function
 */
async function main() {
  console.log('\n' + C.bold + C.cyan + '================================================================' + C.reset);
  console.log(C.bold + C.cyan + '   CINEJOY ON-DEVICE PROXY: STANDALONE SERVICE TEST SUITE       ' + C.reset);
  console.log(C.bold + C.cyan + '================================================================' + C.reset + '\n');

  console.log(C.bold + '► Environment Runtime Profile:' + C.reset);
  console.log('  Node.js:   ' + process.version + ' (Modules: ' + process.versions.modules + ')');
  console.log('  V8 Engine: ' + process.versions.v8);
  console.log('  Platform:  ' + process.platform + ' ' + process.arch);
  console.log('  Target:    LG webOS 8.5.0 (Node 12.22.2 standard)');
  console.log('  Service:   ' + serviceDir);
  console.log('  Port:      ' + activePort + '\n');

  // Shared test context across checks
  let resolvedStreamUrl = null;
  let resolvedOriginalUrl = null;
  let resolvedVariantProxyUrl = null;
  let resolvedMediaSegmentProxyUrl = null;
  let resolvedInitSegmentProxyUrl = null;

  // -------------------------------------------------------------------------
  // Check 1: Syntax compatibility audit
  // -------------------------------------------------------------------------
  await runTest('Check 1: Syntax compatibility audit (Node 12.22.2 strict sweep)', function () {
    assert(fs.existsSync(serviceDir), 'Service directory does not exist: ' + serviceDir);

    const requiredFiles = ['index.js', 'resolver.js', 'hls-proxy.js', 'http-client.js'];
    const violations = [];

    // Helper: Strip comments and string literals while preserving exact line numbers
    function stripCommentsAndStrings(src) {
      let out = '';
      let i = 0;
      const len = src.length;
      while (i < len) {
        if (src[i] === '/' && src[i + 1] === '/') {
          i += 2;
          out += '  ';
          while (i < len && src[i] !== '\n') {
            out += ' ';
            i++;
          }
        } else if (src[i] === '/' && src[i + 1] === '*') {
          i += 2;
          out += '  ';
          while (i < len && !(src[i] === '*' && src[i + 1] === '/')) {
            if (src[i] === '\n') out += '\n';
            else out += ' ';
            i++;
          }
          if (i < len) {
            i += 2;
            out += '  ';
          }
        } else if (src[i] === '"' || src[i] === "'") {
          const q = src[i++];
          out += ' ';
          while (i < len && src[i] !== q) {
            if (src[i] === '\\') {
              out += '  ';
              i += 2;
              continue;
            }
            if (src[i] === '\n') out += '\n';
            else out += ' ';
            i++;
          }
          if (i < len) {
            i++;
            out += ' ';
          }
        } else if (src[i] === '`') {
          i++;
          out += ' ';
          while (i < len && src[i] !== '`') {
            if (src[i] === '\\') {
              out += '  ';
              i += 2;
              continue;
            }
            if (src[i] === '\n') out += '\n';
            else out += ' ';
            i++;
          }
          if (i < len) {
            i++;
            out += ' ';
          }
        } else {
          out += src[i++];
        }
      }
      return out;
    }

    for (let i = 0; i < requiredFiles.length; i++) {
      const filename = requiredFiles[i];
      const filePath = path.join(serviceDir, filename);

      assert(fs.existsSync(filePath), 'Required service file missing: ' + filename);

      const content = fs.readFileSync(filePath, 'utf8');

      // V8 Script Compilation Check
      try {
        new vm.Script(content, { filename: filename, displayErrors: true });
      } catch (scriptErr) {
        violations.push({
          file: filename,
          line: scriptErr.lineNumber || 1,
          type: 'V8 Syntax Error',
          snippet: scriptErr.message
        });
      }

      // AST / Regex Lexical Audit on stripped source (preserves exact line numbers)
      const stripped = stripCommentsAndStrings(content);
      const originalLines = content.split('\n');
      const strippedLines = stripped.split('\n');

      for (let l = 0; l < strippedLines.length; l++) {
        const lineNum = l + 1;
        const strippedLine = strippedLines[l];
        const originalSnippet = originalLines[l] ? originalLines[l].trim() : '';

        // Check 1.1: Optional chaining
        if (/\?\.(?!\d)/.test(strippedLine)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Optional chaining',
            snippet: originalSnippet
          });
        }

        // Check 1.2: Nullish coalescing
        if (/\?\?/.test(strippedLine)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Nullish coalescing',
            snippet: originalSnippet
          });
        }

        // Check 1.3: Numeric separator
        if (/\b\d+_\d+\b/.test(strippedLine)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Numeric separator',
            snippet: originalSnippet
          });
        }

        // Check 1.4: Node 18+ AbortSignal.timeout
        if (/\bAbortSignal\.timeout\b/.test(strippedLine)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'AbortSignal.timeout (Node 18+)',
            snippet: originalSnippet
          });
        }

        // Check 1.5: Node 18+ Readable.fromWeb
        if (/\bReadable\.fromWeb\b/.test(strippedLine)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Readable.fromWeb (Node 18+)',
            snippet: originalSnippet
          });
        }

        // Check 1.6: Node 18+ Global fetch()
        if (/\b(?<![.\w])fetch\s*\(/.test(strippedLine)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'Global fetch() (Node 18+)',
            snippet: originalSnippet
          });
        }

        // Check 1.7: Node 15+ crypto.webcrypto
        if (/\bcrypto\.webcrypto\b/.test(strippedLine)) {
          violations.push({
            file: filename,
            line: lineNum,
            type: 'crypto.webcrypto (Node 15+)',
            snippet: originalSnippet
          });
        }
      }
    }

    if (violations.length > 0) {
      let msg = 'Found ' + violations.length + ' Node 12 incompatible syntax/API occurrences:\n';
      for (let v = 0; v < violations.length; v++) {
        const item = violations[v];
        msg += '    ' + item.file + ':' + item.line + ' [' + item.type + '] ' + item.snippet + '\n';
      }
      throw new Error(msg);
    }

    // Verify crush.wasm exists and is valid
    const wasmPath = path.join(serviceDir, 'crush.wasm');
    assert(fs.existsSync(wasmPath), 'crush.wasm binary is missing from service directory: ' + wasmPath);
    const wasmStat = fs.statSync(wasmPath);
    assert(wasmStat.size >= 65000, 'crush.wasm size is suspiciously small: ' + wasmStat.size + ' bytes');
  });

  // -------------------------------------------------------------------------
  // Check 2: Service startup and local HTTP binding
  // -------------------------------------------------------------------------
  await runTest('Check 2: Service startup and local HTTP binding (127.0.0.1:' + activePort + ')', async function () {
    const isAlreadyRunning = await waitForServer(activePort, 800);
    if (isAlreadyRunning) {
      if (isVerbose) console.log('    Connected to already running service on port ' + activePort);
      return;
    }

    if (isExternalMode) {
      throw new Error('Service is not running on 127.0.0.1:' + activePort + ' and --external mode was requested');
    }

    const entryPoint = path.join(serviceDir, 'index.js');
    assert(fs.existsSync(entryPoint), 'Service entry point missing: ' + entryPoint);

    const env = Object.assign({}, process.env, {
      PORT: activePort.toString(),
      NODE_PATH: process.env.NODE_PATH || '/usr/lib/nodejs:/usr/lib/node_modules'
    });

    serverChildProcess = spawn(process.execPath, [entryPoint], {
      stdio: ['ignore', 'pipe', 'pipe'],
