    });

    serverChildProcess.stdout.on('data', function (data) {
      if (isVerbose) process.stdout.write(C.gray + '[service stdout] ' + data.toString() + C.reset);
    });

    const isReady = await waitForServer(activePort, 6000);
    assert(isReady, 'Service failed to bind and respond on 127.0.0.1:' + activePort + ' within 6000ms');
  });

  // -------------------------------------------------------------------------
  // Check 3: GET /health endpoint response and schema validation
  // -------------------------------------------------------------------------
  await runTest('Check 3: GET /health endpoint response and schema validation', async function () {
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/health',
      method: 'GET'
