  console.log('----------------------------------------------------------------');
  console.log('  Total Checks Run: ' + totalTests);
  console.log('  Passed Checks:    ' + C.green + passedTests + C.reset);
  console.log('  Failed Checks:    ' + (failedTests > 0 ? C.red + failedTests : '0') + C.reset);
  console.log('----------------------------------------------------------------');

  if (serverChildProcess) {
    try {
      serverChildProcess.kill('SIGKILL');
    } catch (_) {}
  }

  if (failedTests > 0) {
    console.log('\n' + C.red + C.bold + 'VERDICT: TEST SUITE FAILED (' + failedTests + ' failures)' + C.reset + '\n');
    process.exit(1);
  } else {
    console.log('\n' + C.green + C.bold + 'VERDICT: ALL 9 CHECKS PASSED (100% SUCCESS)' + C.reset + '\n');
    process.exit(0);
  }
}

